    slug: "a-press-statment-on-why-dennis-miracles-was-arrested-by-eoco",
    title: "A Press Statment On Why Dennis Miracles Was Arrested By EOCO",
    category: "Press Statement",
    author: "Ecomonic & Organised Crime Office",
